class TestSubstringFalsePositives:
    """Commands containing blocked command names as substrings must not be blocked.

    Regression tests for the _PATH word-boundary fix: when _PATH doesn't match
    a path prefix, it asserts \\b so command names can't match mid-word.
    """

    @pytest.mark.parametrize(
        "command",
        [
            # "rg" inside org, target, merge, large, energy
            "ls -lh fetch/org.json",
            "wc -c fetch/org.json",
            "cat target/output.txt",
            "ls merge-results/",
            "wc -l large_file.txt",
            "echo energy savings",
            # "git" inside digit, legit
            "echo digit 42",
            "echo legit push",
            # "grep" inside agrep, pcregrep
            "echo agrep is a tool",
            # "ssh" inside openssh
            "cat /etc/openssh/sshd_config",
            "ls openssh-client/",
            # "make" inside cmake, remake
            "cmake --build .",
            "ls cmake-build-debug/",
            # "scp" inside mscp, lscp
            "echo manuscript page 3",
            # "sc" inside describe, misc, escape, script
            "echo describe delete",
            "echo misc delete flag",
            # "sudo" inside pseudocode
            "echo pseudocode example",
            # "su" inside result, issue, resume
            "echo result output",
            # "gh" inside sigh, high, weigh
            "echo sigh api response",
            "echo high issue count",
            # "reg" inside regex, register, region
            "echo regex delete pattern",
            # "shred" inside unshred
            "echo unshred file.dat",
            # "truncate" inside ftruncate
            "echo ftruncate call",
            # "chmod" inside fchmod
            "echo fchmod 777 call",
            # "rsync" inside lrsync
            "echo lrsync run",
            # "format" inside reformat
            "echo reformat C: drive",
            # "del" inside model, delete
            "echo model /s flag",
            # "rd" inside word, bird
            "echo word /s end",
        ],
    )
    def test_substring_not_blocked(self, command: str) -> None:
        assert block_commands.check_command(command) is None


class TestMain:
    def test_blocked_command_exits_2(self, monkeypatch: pytest.MonkeyPatch) -> None:
        data = {"tool_input": {"command": "git push origin main"}}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        with pytest.raises(SystemExit) as exc_info:
            block_commands.main()
        assert exc_info.value.code == 2

    def test_allowed_command_exits_normally(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_input": {"command": "git status"}}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        block_commands.main()  # should not raise

    def test_empty_command_exits_normally(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_input": {"command": ""}}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        block_commands.main()  # should not raise

    def test_no_command_field_exits_normally(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_input": {}}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        block_commands.main()  # should not raise

    def test_no_tool_input_exits_normally(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_name": "Bash"}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        block_commands.main()  # should not raise

    def test_bad_json_no_crash(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setattr(sys, "stdin", io.StringIO("not json"))
        block_commands.main()  # should not raise

    def test_empty_stdin_no_crash(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setattr(sys, "stdin", io.StringIO(""))
        block_commands.main()  # should not raise

    def test_blocked_message_on_stderr(
        self, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
    ) -> None:
        data = {"tool_input": {"command": "sudo rm -rf /"}}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        with pytest.raises(SystemExit):
            block_commands.main()
        captured = capsys.readouterr()
        assert "BLOCKED: sudo is not allowed" in captured.err

    def test_non_dict_tool_input_uses_flat_command(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_input": "not a dict", "command": "git push origin main"}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        with pytest.raises(SystemExit) as exc_info:
            block_commands.main()
        assert exc_info.value.code == 2

    def test_non_dict_tool_input_no_command(
        self, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        data = {"tool_input": "not a dict"}
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps(data)))
        block_commands.main()  # should not raise
